/* @autogenerated */
import { fakeAsync, tick } from '@angular/core/testing';
import { BehaviorSubject, filter, of } from 'rxjs';
import { IdentityNotConfiguredError, IdentityService } from './identity.service';
import { IdentityHandler, IdentityProvider } from './identity-provider.interface';
import { RuntimeConfigService } from '@shared/context/config/app-config.service';
import { Logger } from '@shared/context/observability/logger.service';

function handlerSpy(): IdentityHandler {
  return {
    bootstrap: jasmine.createSpy('bootstrap').and.returnValue(of(undefined)),
    token$: jasmine.createSpy('token$').and.returnValue(of('access-1')),
    login: jasmine.createSpy('login'),
    logout: jasmine.createSpy('logout'),
  };
}

// Como RuntimeConfigService.value$: no emite hasta que la configuración ha cargado (null)
function configOf(identity$: BehaviorSubject<any>): RuntimeConfigService {
  return { value$: () => identity$.pipe(filter((v) => v !== null)) } as unknown as RuntimeConfigService;
}

let logger: jasmine.SpyObj<Logger>;

describe('IdentityService', () => {
  beforeEach(() => (logger = jasmine.createSpyObj<Logger>('Logger', ['error'])));

  it('selects handler based on identity config and delegates actions', () => {
    const handler = handlerSpy();
    const provider: IdentityProvider = {
      accept: (type) => (type === 'oidc' ? handler : null),
    };

    const service = new IdentityService(configOf(new BehaviorSubject({ main: { type: 'oidc' } })), [provider], logger);

    service.bootstrap('main').subscribe();
    service.login('main');
    service.logout('main');

    expect(handler.bootstrap).toHaveBeenCalled();
    expect(handler.login).toHaveBeenCalled();
    expect(handler.logout).toHaveBeenCalled();
  });

  it('exposes the handler token', () => {
    const handler = handlerSpy();
    const service = new IdentityService(
      configOf(new BehaviorSubject({ main: { type: 'oidc' } })),
      [{ accept: () => handler }],
      logger,
    );

    let token: string | null = null;
    service.token('main').subscribe((t) => (token = t));

    expect(token as string | null).toBe('access-1');
  });

  it('bootstrap fails with IdentityNotConfiguredError when the type has no handler', () => {
    const service = new IdentityService(
      configOf(new BehaviorSubject({ main: { type: 'typo' } })),
      [{ accept: () => null }],
      logger,
    );

    let error: unknown;
    service.bootstrap('main').subscribe({ error: (e) => (error = e) });

    expect(error).toEqual(jasmine.any(IdentityNotConfiguredError));
    expect((error as IdentityNotConfiguredError).identity).toBe('main');
  });

  it('waits for the configuration before resolving bootstrap', () => {
    const handler = handlerSpy();
    const identity$ = new BehaviorSubject<any>(null);
    const service = new IdentityService(configOf(identity$), [{ accept: () => handler }], logger);

    let done = false;
    service.bootstrap('main').subscribe(() => (done = true));
    expect(done).toBeFalse();

    identity$.next({ main: { type: 'oidc' } });
    expect(done).toBeTrue();
  });

  it('does not reconfigure when the configuration emits the same value', () => {
    const accept = jasmine.createSpy('accept').and.returnValue(handlerSpy());
    const identity$ = new BehaviorSubject<any>({ main: { type: 'oidc' } });
    new IdentityService(configOf(identity$), [{ accept }], logger);

    identity$.next({ main: { type: 'oidc' } });
    expect(accept).toHaveBeenCalledTimes(1);

    identity$.next({ main: { type: 'oidc', other: true } });
    expect(accept).toHaveBeenCalledTimes(2);
  });

  it('logs error when multiple providers match the same identity type', () => {
    const handler = handlerSpy();

    new IdentityService(
      configOf(new BehaviorSubject({ main: { type: 'oidc' } })),
      [{ accept: () => handler }, { accept: () => handler }],
      logger,
    );

    expect(logger.error).toHaveBeenCalledWith(jasmine.stringContaining('More than one identity handler'));
  });

  it('logs error when no provider matches the identity type', () => {
    new IdentityService(
      configOf(new BehaviorSubject({ main: { type: 'unknown-type' } })),
      [{ accept: () => null }],
      logger,
    );

    expect(logger.error).toHaveBeenCalledWith(jasmine.stringContaining('No identity handler'));
  });

  it('login is a no-op when the key is not in the map', () => {
    const service = new IdentityService(configOf(new BehaviorSubject({})), [], logger);

    expect(() => service.login('nonexistent')).not.toThrow();
  });

  it('logout is a no-op when the key is not in the map', () => {
    const service = new IdentityService(configOf(new BehaviorSubject({})), [], logger);

    expect(() => service.logout('nonexistent')).not.toThrow();
  });

  it('marks the redirect while login or logout leave the page, and clears it after the timeout', fakeAsync(() => {
    const handler = handlerSpy();
    const provider: IdentityProvider = { accept: () => handler };
    const service = new IdentityService(configOf(new BehaviorSubject({ main: { type: 'oidc' } })), [provider], logger);

    expect(service.redirecting()).toBeNull();
    service.login('main');
    expect(service.redirecting()).toBe('login');
    tick(30_000);
    expect(service.redirecting()).toBeNull();

    service.logout('main');
    expect(service.redirecting()).toBe('logout');
    tick(30_000);
  }));

  it('does not mark a redirect when there is no handler', () => {
    const service = new IdentityService(configOf(new BehaviorSubject({})), [], logger);

    service.login('nonexistent');

    expect(service.redirecting()).toBeNull();
  });
});
